function _rng(seed){ var s=seed>>>0||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }
function qInit(rows,cols){ var Q=[]; for(var r=0;r<rows;r++) for(var c=0;c<cols;c++) Q.push([0,0,0,0]); return Q; }
function qBest(Q,s){ var b=0,bv=Q[s][0]; for(var i=1;i<4;i++) if(Q[s][i]>bv){bv=Q[s][i];b=i;} return b; }
function qStep(Q,rows,cols,s,a,r,ns,terminal,alpha,gamma){
  var maxNext=0; if(!terminal){ var nq=Q[ns]; for(var i=0;i<4;i++) if(nq[i]>maxNext) maxNext=nq[i]; }
  var target=r+gamma*maxNext; Q[s][a]+=alpha*(target-Q[s][a]); return Q[s][a]; }
// gridworld: 4x4, goal at (rows-1,cols-1). actions 0 up,1 down,2 left,3 right
function gwStep(rows,cols,s,a){ var r=Math.floor(s/cols), c=s%cols;
  if(a===0) r=Math.max(0,r-1); else if(a===1) r=Math.min(rows-1,r+1); else if(a===2) c=Math.max(0,c-1); else if(a===3) c=Math.min(cols-1,c+1);
  return r*cols+c; }
function gwReward(s,goal){ return s===goal?10:-1; }
function gwTerminal(s,goal){ return s===goal; }
var EXPORTS={qInit:qInit, qBest:qBest, qStep:qStep, gwStep:gwStep, gwReward:gwReward, gwTerminal:gwTerminal, _rng:_rng};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
